UPDATE remit_payments SET package_json = #{packageJson}, nonce = #{nonce}, commitment = #{commitment}, attestation_id = #{attestationId},
       updated_at = #{at}
 WHERE id = #{id} AND attestation_id IS NULL

mapper.sql:
org_id = #{orgId}

  AND (UPPER(id) LIKE #{like} ESCAPE '!' OR UPPER(quote_id) LIKE #{like} ESCAPE '!'
    OR UPPER(COALESCE(chain_tx, '')) LIKE #{like} ESCAPE '!'
    OR EXISTS (SELECT 1 FROM remit_events e WHERE e.payment_id = remit_payments.id
               AND e.type = 'PAYOUT_COMPLETED' AND UPPER(COALESCE(JSON_EXTRACT(e.payload, '$.bank_reference'), '')) LIKE #{like} ESCAPE '!')
    OR EXISTS (SELECT 1 FROM remit_events e WHERE e.payment_id = remit_payments.id
               AND e.type = 'BANK_EVIDENCE_SUBMITTED' AND (UPPER(COALESCE(JSON_EXTRACT(e.payload, '$.bankInstruction.sourceMessage.uetr'), '')) LIKE #{like} ESCAPE '!' OR UPPER(COALESCE(JSON_EXTRACT(e.payload, '$.bankInstruction.sourceMessage.instructionId'), '')) LIKE #{like} ESCAPE '!' OR UPPER(COALESCE(JSON_EXTRACT(e.payload, '$.bankInstruction.sourceMessage.endToEndId'), '')) LIKE #{like} ESCAPE '!' OR UPPER(COALESCE(JSON_EXTRACT(e.payload, '$.bankInstruction.sourceMessage.messageId'), '')) LIKE #{like} ESCAPE '!' OR UPPER(COALESCE(JSON_EXTRACT(e.payload, '$.bankApproval.approvalRef'), '')) LIKE #{like} ESCAPE '!'))
    OR EXISTS (SELECT 1 FROM remit_events e WHERE e.payment_id = remit_payments.id
               AND e.type = 'BANK_AUTHORIZATION_VERIFIED' AND UPPER(COALESCE(JSON_EXTRACT(e.payload, '$.bank_authorization.instruction_ref'), '')) LIKE #{like} ESCAPE '!'))


  AND EXISTS (SELECT 1 FROM remit_source_refs r WHERE r.payment_id = remit_payments.id AND r.org_id = #{orgId}
    AND r.uetr = #{sourceUetr}
    AND r.content = #{sourceContent}
    AND r.value_date = #{sourceValueDate})


  AND state IN #{s}

AND created_at >= #{from}
AND created_at <= #{to}

mapper.select:
SELECT  FROM remit_payments WHERE 

  AND (created_at < #{cursorAt} OR (created_at = #{cursorAt} AND id < #{cursorId}))

ORDER BY created_at DESC, id DESC LIMIT #{limit}

mapper.update:
UPDATE remit_jobs
   SET attempts = attempts + 1, lease_expires_at = UTC_TIMESTAMP(3) + INTERVAL #{leaseSeconds} SECOND, updated_at = UTC_TIMESTAMP(3)
 WHERE id = #{id} AND state = 'running' AND lease_owner = #{owner}

UPDATE remit_jobs
   SET call_started_at = UTC_TIMESTAMP(3), lease_expires_at = UTC_TIMESTAMP(3) + INTERVAL #{leaseSeconds} SECOND, updated_at = UTC_TIMESTAMP(3)
 WHERE id = #{id} AND state = 'running' AND lease_owner = #{owner}

UPDATE remit_jobs
   SET state = 'queued', lease_owner = NULL, lease_expires_at = NULL, next_attempt_at = UTC_TIMESTAMP(3), updated_at = UTC_TIMESTAMP(3)
 WHERE id = #{id} AND state = 'running' AND lease_owner = #{owner}

UPDATE remit_jobs
   SET state = #{state}, open_slot = NULL, lease_owner = NULL, lease_expires_at = NULL, last_error = #{error}, updated_at = UTC_TIMESTAMP(3)
 WHERE id = #{id} AND state = 'running' AND lease_owner = #{owner}

UPDATE remit_jobs
   SET state = #{state}, open_slot = NULL, lease_owner = NULL, lease_expires_at = NULL, last_error = #{error}, updated_at = UTC_TIMESTAMP(3)
 WHERE id = #{id}
